// Validate input + derive idempotency key when missing
const crypto = require('crypto');
const body = $input.first().json.body ?? $input.first().json;

const story_id = body.story_id ?? null;
const source_type = body.source_type;
const source_url = body.source_url ?? null;
const source_storage_path = body.source_storage_path ?? null;
let idempotency_key = body.idempotency_key ?? null;
const kind = body.kind ?? (source_type === 'url_scrape' ? 'ingest_scrape' : 'ingest_upload');

if (!source_type) {
  throw new Error('source_type required');
}

if (!idempotency_key) {
  const seed = `${source_type}|${source_url ?? ''}|${source_storage_path ?? ''}|${story_id ?? 'global'}|${Date.now()}`;
  idempotency_key = crypto.createHash('sha256').update(seed).digest('hex');
}

return [{ json: { story_id, kind, source_type, source_url, source_storage_path, idempotency_key } }];

// Call start_web_artifact_ingest RPC via PostgREST (service_role JWT)
const gatewayUrl = $env.AISHA_GATEWAY_URL;
const serviceKey = $env.AISHA_SERVICE_KEY;
const { story_id, kind, source_type, source_url, source_storage_path, idempotency_key } = $input.first().json;

const rpcRes = await fetch(`${gatewayUrl}/rest/v1/rpc/start_web_artifact_ingest`, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'accept': 'application/json',
    'apikey': serviceKey,
    'authorization': `Bearer ${serviceKey}`
  },
  body: JSON.stringify({
    p_story_id: story_id,
    p_kind: kind,
    p_source_type: source_type,
    p_source_url: source_url,
    p_source_storage_path: source_storage_path,
    p_idempotency_key: idempotency_key,
    p_metadata: {}
  })
});

if (!rpcRes.ok) {
  const text = await rpcRes.text();
  throw new Error(`start_web_artifact_ingest failed: ${rpcRes.status} ${text}`);
}
const job_id = (await rpcRes.json()).toString().replace(/"/g, '');

return [{ json: { ...$input.first().json, job_id } }];

// Call svc-web-artifact /parse via gateway
const gatewayUrl = $env.AISHA_GATEWAY_URL;
const serviceKey = $env.AISHA_SERVICE_KEY;
const { job_id, source_type, source_url, source_storage_path } = $input.first().json;

const started = Date.now();
const parseRes = await fetch(`${gatewayUrl}/functions/v1/web-artifact-parse`, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'authorization': `Bearer ${serviceKey}`
  },
  body: JSON.stringify({ job_id, source_type, source_url, source_storage_path })
});

const duration_ms = Date.now() - started;
const parseBody = await parseRes.text();

if (!parseRes.ok) {
  // Service has already called fail_web_artifact_ingest internally; record audit at WF level too.
  await fetch(`${gatewayUrl}/rest/v1/rpc/log_integration_action`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'apikey': serviceKey,
      'authorization': `Bearer ${serviceKey}`
    },
    body: JSON.stringify({
      p_integration: 'n8n',
      p_action_key: 'web_artifact.ingest.fail',
      p_payload: { job_id, status: parseRes.status, detail: parseBody, duration_ms },
      p_tags: ['stack', 'story', 'web_artifact', 'ingest', 'fail']
    })
  });
  throw new Error(`parse failed: ${parseRes.status} ${parseBody}`);
}

await fetch(`${gatewayUrl}/rest/v1/rpc/log_integration_action`, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'apikey': serviceKey,
    'authorization': `Bearer ${serviceKey}`
  },
  body: JSON.stringify({
    p_integration: 'n8n',
    p_action_key: 'web_artifact.ingest.complete',
    p_payload: { job_id, duration_ms },
    p_tags: ['stack', 'story', 'web_artifact', 'ingest', 'complete']
  })
});

return [{ json: { job_id, status: 'ready_for_review', duration_ms } }];
